const INFO = {"fecha": "22/06/2026 08:46", "er_ok": 5, "cp_ok": 5, "periodos": 5};
const ER = P.estado_resultado;
const CP = P.costos_prestacionales;
const PERIODOS = P.periodos;

const OS_COLOR={OSPEVIC:"#0A1F8C",OSPIF:"#0BC8FA",OSPLYFC:"#7A52F4",OSPM:"#0E9F6E",OSSURRBAC:"#F2B705",AMSURRBAC:"#E74C3C",UOM:"#6B7691"};
const CAT_COLOR={Ambulatorio:"#0BC8FA",Internado:"#0A1F8C",Capitado:"#7A52F4",Traslado:"#F2B705",Refacturacion:"#E74C3C",Protesis:"#0E9F6E",Intereses:"#6B7691","Centro Medico":"#2ECC71","Sin Clasificacion":"#9CA8C0"};

const fmtMoney=v=>"$ "+new Intl.NumberFormat('es-AR',{maximumFractionDigits:0}).format(Math.round(v));
const fmtMoneyShort=v=>{const a=Math.abs(v),s=v<0?"-":"";if(a>=1e9)return s+"$ "+(a/1e9).toFixed(2).replace('.',',')+" B";if(a>=1e6)return s+"$ "+(a/1e6).toFixed(1).replace('.',',')+" M";if(a>=1e3)return s+"$ "+(a/1e3).toFixed(0)+" K";return s+"$ "+a.toFixed(0)};
const fmtMoneyFull=v=>{const s=v<0?"-":"";return s+"$ "+new Intl.NumberFormat('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Math.abs(v))};
const fmtPct=v=>(v*100).toFixed(1).replace('.',',')+" %";
const fmtNum=v=>new Intl.NumberFormat('es-AR').format(v);

let currentTab="estado";
let currentView=PERIODOS.length?PERIODOS[PERIODOS.length-1]:"compare";
let cmpSel=new Set(PERIODOS);
let erCmpPeriodo=null;
let erCmpOn=true;
let charts={};
function destroyChart(k){if(charts[k]){charts[k].destroy();delete charts[k];}}
function getCmpPeriodos(){const sel=PERIODOS.filter(p=>cmpSel.has(p));return sel.length?sel:PERIODOS;}

function buildPeriodButtons(){
  let h="";
  PERIODOS.forEach(p=>{h+=`<button class="period-btn" data-view="${p}">${P.periodos_short[p]}</button>`;});
  if(PERIODOS.length>1) h+=`<button class="period-btn" data-view="compare">Comparativo</button>`;
  document.getElementById("period-selector").innerHTML=h;
  document.querySelectorAll(".period-btn").forEach(b=>b.addEventListener("click",()=>setView(b.dataset.view)));
}
function buildCmpFilters(){
  if(PERIODOS.length<2) return;
  const h=`<div class="hint" style="margin-right:6px">Meses a comparar:</div>`+PERIODOS.map(p=>
    `<label class="hm-chip"><input type="checkbox" data-cmp="${p}" ${cmpSel.has(p)?"checked":""}> ${P.periodos_short[p]}</label>`
  ).join("")+`<a href="#" class="hm-chip" data-cmp-all="1" style="text-decoration:none">Todos</a>`;
  document.querySelectorAll(".cmp-period-filters").forEach(el=>el.innerHTML=h);
  document.querySelectorAll(".cmp-period-filters input[data-cmp]").forEach(cb=>cb.addEventListener("change",e=>{
    const p=e.target.dataset.cmp;
    if(e.target.checked) cmpSel.add(p); else cmpSel.delete(p);
    if(cmpSel.size===0) cmpSel=new Set(PERIODOS);
    buildCmpFilters();
    if(currentView==="compare") render();
  }));
  document.querySelectorAll(".cmp-period-filters [data-cmp-all]").forEach(a=>a.addEventListener("click",e=>{
    e.preventDefault();
    cmpSel=new Set(PERIODOS);
    buildCmpFilters();
    if(currentView==="compare") render();
  }));
}

// ===== ESTADO DE RESULTADO =====
function erComparisonOptions(periodo){
  return PERIODOS.filter(p=>p!==periodo&&ER[p]);
}
function erDefaultCmp(periodo){
  const idx=PERIODOS.indexOf(periodo);
  if(idx>0&&ER[PERIODOS[idx-1]]) return PERIODOS[idx-1];
  const opts=erComparisonOptions(periodo);
  return opts.length?opts[opts.length-1]:null;
}
function erCmpToggle(){
  erCmpOn=document.getElementById("er-cmp-toggle").checked;
  erKpisSingle(currentView);
}
function erCmpSelectChange(){
  erCmpPeriodo=document.getElementById("er-cmp-select").value;
  erKpisSingle(currentView);
}
function erKpisSingle(periodo){
  const m=ER[periodo];const t=m.totals;
  const lbl=p=>P.periodos_short[p]||p;
  const opts=erComparisonOptions(periodo);
  if(!erCmpPeriodo||!opts.includes(erCmpPeriodo)) erCmpPeriodo=erDefaultCmp(periodo);
  const cmpAvailable=opts.length>0&&erCmpPeriodo;
  const showCmp=cmpAvailable&&erCmpOn;
  const cp=cmpAvailable?ER[erCmpPeriodo].totals:null;
  const ro=t.ingresos_netos-t.costos_prestacionales;
  const cro=cp?(cp.ingresos_netos-cp.costos_prestacionales):null;

  const toggleWrap=document.getElementById("er-cmp-toggle-wrap");
  if(cmpAvailable){
    toggleWrap.style.display="";
    document.getElementById("er-cmp-toggle").checked=erCmpOn;
    document.getElementById("er-cmp-select").innerHTML=opts.map(p=>`<option value="${p}" ${p===erCmpPeriodo?"selected":""}>${P.periodos_label[p]||lbl(p)}</option>`).join("");
    document.getElementById("er-cmp-select").style.display=erCmpOn?"":"none";
  } else {
    toggleWrap.style.display="none";
  }

  function diffPct(cur,prev){
    if(prev===null||prev===undefined||prev===0) return null;
    return ((cur-prev)/Math.abs(prev))*100;
  }
  function varCell(cur,prev,goodIfDown){
    if(!showCmp) return "";
    const d=diffPct(cur,prev);
    if(d===null) return `<td class="val var-cell cmp-col">-</td>`;
    const good=goodIfDown?d<=0:d>=0;
    const cls=good?"var-pos":"var-neg";
    const sign=d>0?"+":"";
    return `<td class="val var-cell cmp-col"><span class="${cls}">${sign}${d.toFixed(1).replace('.',',')}%</span></td>`;
  }
  function valCell(v,extra=""){return `<td class="val ${extra}">${fmtMoneyShort(v)}</td>`;}
  function cmpValCell(v,extra=""){return showCmp?`<td class="val cmp-col ${extra}">${v===null||v===undefined?"-":fmtMoneyShort(v)}</td>`:"";}

  const colspan=showCmp?4:2;
  const cmpHeader=showCmp?`<th class="cmp-col">${lbl(erCmpPeriodo)}</th><th class="cmp-col var-col">Var.</th>`:"";

  let rows=`<tr><th>Concepto</th><th>${lbl(periodo)}</th>${cmpHeader}</tr>`;
  rows+=`<tr class="line-item"><td class="concepto">Ingresos Netos</td>${valCell(t.ingresos_netos)}${cmpValCell(cp?cp.ingresos_netos:null)}${varCell(t.ingresos_netos,cp?cp.ingresos_netos:null,false)}</tr>`;
  rows+=`<tr class="sub"><td colspan="${colspan}">+ Ingresos Extras (inf.): ${fmtMoneyShort(t.ingresos_extras)} · ${fmtPct(t.ingresos_extras/t.ingresos_netos)} del ingreso</td></tr>`;
  rows+=`<tr class="line-item"><td class="concepto"><span class="ico">−</span>Costos Prestacionales</td>${valCell(t.costos_prestacionales,"neg")}${cmpValCell(cp?cp.costos_prestacionales:null,"neg")}${varCell(t.costos_prestacionales,cp?cp.costos_prestacionales:null,true)}</tr>`;
  rows+=`<tr class="sub"><td colspan="${colspan}">${fmtPct(t.costos_prestacionales/t.ingresos_netos)} de ingresos netos${cp?` (vs ${fmtPct(cp.costos_prestacionales/cp.ingresos_netos)} ${lbl(erCmpPeriodo)})`:""}</td></tr>`;
  rows+=`<tr class="subtotal"><td class="concepto">= Resultado Operativo</td>${valCell(ro)}${cmpValCell(cro)}${varCell(ro,cro,false)}</tr>`;
  rows+=`<tr class="line-item"><td class="concepto"><span class="ico">−</span>Costos Fijos</td>${valCell(t.costos_fijos,"neg")}${cmpValCell(cp?cp.costos_fijos:null,"neg")}${varCell(t.costos_fijos,cp?cp.costos_fijos:null,true)}</tr>`;
  rows+=`<tr class="sub"><td colspan="${colspan}">${fmtPct(t.costos_fijos/t.ingresos_netos)} de ingresos netos${cp?` (vs ${fmtPct(cp.costos_fijos/cp.ingresos_netos)} ${lbl(erCmpPeriodo)})`:""}</td></tr>`;
  rows+=`<tr class="subtotal"><td class="concepto">= Resultado AIEI</td>${valCell(t.resultado_antes,t.resultado_antes<0?"neg":"")}${cmpValCell(cp?cp.resultado_antes:null,cp&&cp.resultado_antes<0?"neg":"")}${varCell(t.resultado_antes,cp?cp.resultado_antes:null,false)}</tr>`;
  rows+=`<tr class="line-item"><td class="concepto"><span class="ico">−</span>Impuestos</td>${valCell(t.impuestos)}${cmpValCell(cp?cp.impuestos:null)}${varCell(t.impuestos,cp?cp.impuestos:null,true)}</tr>`;
  rows+=`<tr class="final"><td class="concepto">= Resultado Neto</td>${valCell(t.resultado_neto)}${cmpValCell(cp?cp.resultado_neto:null)}${varCell(t.resultado_neto,cp?cp.resultado_neto:null,false)}</tr>`;
  document.getElementById("er-pl-table").innerHTML=rows;

  let note=`Margen Neto ${lbl(periodo)}: <strong>${fmtPct(t.margen)}</strong>`;
  if(cp&&cp.ingresos_netos) note+=` &nbsp;|&nbsp; ${lbl(erCmpPeriodo)}: <strong>${fmtPct(cp.resultado_neto/cp.ingresos_netos)}</strong>`;
  document.getElementById("er-pl-note").innerHTML=note;

  let afilMeta="Total cartera";
  if(cp&&cp.afiliados){
    const d=((t.afiliados-cp.afiliados)/Math.abs(cp.afiliados))*100;
    const cls=d>=0?"var-pos":"var-neg";
    afilMeta=`<span class="${cls}">${d>=0?"▲":"▼"} ${Math.abs(d).toFixed(1).replace('.',',')}%</span> vs ${lbl(erCmpPeriodo)} (${fmtNum(cp.afiliados)})`;
  }
  document.getElementById("er-kpis").innerHTML=`
  <div class="kpi-card primary"><div class="kpi-label">Afiliados</div><div class="kpi-value">${fmtNum(t.afiliados)}</div><div class="kpi-meta">${afilMeta}</div></div>
  <div class="kpi-card"><div class="kpi-label">Capita Promedio</div><div class="kpi-value">$ ${fmtNum(Math.round(t.capita_promedio_ponderado))}</div><div class="kpi-meta">Ponderado por afiliados</div></div>
  <div class="kpi-card"><div class="kpi-label">Ingresos Netos</div><div class="kpi-value">${fmtMoneyShort(t.ingresos_netos)}</div><div class="kpi-meta">Capita + Refuerzo + Extras - NC/D</div></div>
  <div class="kpi-card"><div class="kpi-label">Ingresos Extras</div><div class="kpi-value">${fmtMoneyShort(t.ingresos_extras)}</div><div class="kpi-meta">${fmtPct(t.ingresos_extras/t.ingresos_netos)} del ingreso</div></div>
  <div class="kpi-card warn"><div class="kpi-label">Costos Prestacionales</div><div class="kpi-value">${fmtMoneyShort(t.costos_prestacionales)}</div><div class="kpi-meta">${fmtPct(t.costos_prestacionales/t.ingresos_netos)} / Ing. netos</div></div>
  <div class="kpi-card purple"><div class="kpi-label">Costos Fijos</div><div class="kpi-value">${fmtMoneyShort(t.costos_fijos)}</div><div class="kpi-meta">${fmtPct(t.costos_fijos/t.ingresos_netos)} / Ing. netos</div></div>
  <div class="kpi-card negative"><div class="kpi-label">Resultado AIEI</div><div class="kpi-value">${fmtMoneyShort(t.resultado_antes)}</div><div class="kpi-meta">Margen ${fmtPct(t.resultado_antes/t.ingresos_netos)}</div></div>
  <div class="kpi-card"><div class="kpi-label">Impuestos</div><div class="kpi-value">${fmtMoneyShort(t.impuestos)}</div><div class="kpi-meta">IIBB + IVA + Munic</div></div>
  <div class="kpi-card positive"><div class="kpi-label">Resultado Neto</div><div class="kpi-value">${fmtMoneyShort(t.resultado_neto)}</div><div class="kpi-meta">Margen ${fmtPct(t.margen)}</div></div>`;
}
function erKpisCompare(){
  const selAll=getCmpPeriodos();
  const sel=selAll.filter(p=>ER[p]);
  if(!sel.length){document.getElementById("er-kpis-compare").innerHTML="<p style='color:var(--muted);padding:14px'>No hay datos de Estado de Resultado para los meses seleccionados.</p>";return;}
  const last=sel[sel.length-1],prev=sel.length>1?sel[sel.length-2]:null;
  const lt=ER[last].totals,pt=prev?ER[prev].totals:null;
  const kpis=[["Afiliados","afiliados",fmtNum,false],["Ingresos Netos","ingresos_netos",fmtMoneyShort,false],["Costos Prestacionales","costos_prestacionales",fmtMoneyShort,true],["Costos Fijos","costos_fijos",fmtMoneyShort,true],["Impuestos","impuestos",fmtMoneyShort,true],["Resultado Neto","resultado_neto",fmtMoneyShort,false]];
  document.getElementById("er-kpis-compare").innerHTML=kpis.map(([lab,k,fmt,inv])=>{
    const lv=lt[k],pv=pt?pt[k]:null;
    let meta=`Ultimo: ${P.periodos_short[last]}`;
    if(pv!==null&&pv!==0){const d=((lv-pv)/Math.abs(pv))*100;const dc=inv?(d>=0?"delta-neg":"delta-pos"):(d>=0?"delta-pos":"delta-neg");meta=`<span class="${dc}">${d>=0?"▲":"▼"} ${Math.abs(d).toFixed(1).replace('.',',')}%</span> vs ${P.periodos_short[prev]}`;}
    return `<div class="kpi-card"><div class="kpi-label">${lab}</div><div class="kpi-value">${fmt(lv)}</div><div class="kpi-meta">${meta}</div></div>`;
  }).join("");
}
