function erCmpTablePopulateOsFilter(sel){
  const dd=document.getElementById("er-cmp-os-filter");
  const cur=dd.value;
  const osList=sel.length?ER[sel[0]].obras_sociales.map(o=>o.code):[];
  dd.innerHTML='<option value="TOTAL">Total (todas las OS)</option>'+osList.map(c=>`<option value="${c}"${c===cur?" selected":""}>${c}</option>`).join("");
  if(cur&&cur!=="TOTAL"&&osList.includes(cur)) dd.value=cur;
}
function erCmpTable(){
  const sel=getCmpPeriodos().filter(p=>ER[p]);
  if(!sel.length){document.getElementById("er-cmp-table").innerHTML="<thead></thead><tbody><tr><td style='padding:14px;color:var(--muted)'>Sin datos de Estado de Resultado para los meses seleccionados.</td></tr></tbody>";return;}
  erCmpTablePopulateOsFilter(sel);
  const osFilter=document.getElementById("er-cmp-os-filter").value;
  const byOs=osFilter&&osFilter!=="TOTAL";
  // helper: get value for a period, key — from totals or from the selected OS
  function getVal(p,k){
    if(!byOs) return ER[p].totals[k];
    const o=ER[p].obras_sociales.find(x=>x.code===osFilter);
    return o?(o[k]??0):0;
  }
  const titulo=byOs?` <span style="background:${OS_COLOR[osFilter]||"#0A1F8C"}22;color:${OS_COLOR[osFilter]||"#0A1F8C"};padding:2px 8px;border-radius:4px;font-size:12px;font-weight:700">${osFilter}</span>`:"";
  let h=`<thead><tr><th>Concepto${titulo}</th>`+sel.map(p=>`<th class="right">${P.periodos_label[p]}</th>`).join("")+"</tr></thead><tbody>";
  // helper para fila normal
  const row=(lab,k,fmt,isRed,isBold,isSub)=>{
    const style=`${isRed?"color:#E74C3C;":""}${isBold?"font-weight:700;":""}`;
    const tdStyle=`${isRed?"color:#E74C3C;":""}${isBold?"font-weight:700;":""}`;
    const trClass=isSub?"final":"";
    h+=`<tr${trClass?` class="${trClass}"`:""}>`;
    h+=`<td class="metric" style="${style}">${lab}</td>`;
    sel.forEach(p=>{h+=`<td class="right" style="${tdStyle}">${fmt(getVal(p,k))}</td>`;});
    h+="</tr>";
  };
  // helper para fila calculada (no viene de una key, sino de una formula)
  const rowCalc=(lab,fn,fmt,isRed,isBold,isSub)=>{
    const style=`${isRed?"color:#E74C3C;":""}${isBold?"font-weight:700;":""}`;
    const trClass=isSub?"final":"";
    h+=`<tr${trClass?` class="${trClass}"`:""}>`;
    h+=`<td class="metric" style="${style}">${lab}</td>`;
    sel.forEach(p=>{h+=`<td class="right" style="${style}">${fmt(fn(p))}</td>`;});
    h+="</tr>";
  };
  // helper para fila de detalle (sub-ítem, indentado, muted)
  const rowDetail=(lab,k,fmt)=>{
    const anyVal=sel.some(p=>getVal(p,k)>0);
    if(!anyVal) return;
    h+=`<tr class="detail-row">`;
    h+=`<td class="metric" style="padding-left:22px;font-size:12px;color:var(--muted,#888)">↳ ${lab}</td>`;
    sel.forEach(p=>{
      const v=getVal(p,k);
      h+=`<td class="right" style="font-size:12px;color:var(--muted,#888)">${v>0?fmt(v):"–"}</td>`;
    });
    h+="</tr>";
  };
  row("Afiliados","afiliados",fmtNum,false,false,false);
  row("Ingresos Netos","ingresos_netos",fmtMoneyShort,false,true,false);
  if(!byOs) row("Ingresos Extras","ingresos_extras",fmtMoneyShort,false,false,false);
  rowDetail("Extracapita","extracapita_ingreso",fmtMoneyShort);
  row("− Costos Variables","costos_prestacionales",fmtMoneyShort,true,false,false);
  rowCalc("= Resultado Operativo",p=>getVal(p,"ingresos_netos")-getVal(p,"costos_prestacionales"),fmtMoneyShort,false,true,true);
  row("− Costos Fijos","costos_fijos",fmtMoneyShort,true,false,false);
  row("= Resultado Antes Imp.","resultado_antes",fmtMoneyShort,false,true,false);
  if(!byOs) row("− Impuestos","impuestos",fmtMoneyShort,true,false,false);
  row("Resultado Neto","resultado_neto",fmtMoneyShort,false,true,true);
  row("Margen Neto","margen",fmtPct,false,false,false);
  document.getElementById("er-cmp-table").innerHTML=h+"</tbody>";
}

// ===== COSTOS FIJOS =====
const CF_PALETTE=["#0A1F8C","#0BC8FA","#7A52F4","#0E9F6E","#F2B705","#E74C3C","#6B7691","#2ECC71","#9CA8C0"];
function cfKpisSingle(periodo){
  const m=ER[periodo];const items=m.costos_fijos_items||[];const total=m.totals.costos_fijos;
  const top=items.length?[...items].sort((a,b)=>b.total-a.total)[0]:null;
  document.getElementById("cf-kpis").innerHTML=`
  <div class="kpi-card primary"><div class="kpi-label">Total Costos Fijos</div><div class="kpi-value">${fmtMoneyShort(total)}</div><div class="kpi-meta">${fmtPct(total/m.totals.ingresos_netos)} de ingresos netos</div></div>
  <div class="kpi-card"><div class="kpi-label"># Items</div><div class="kpi-value">${items.length}</div><div class="kpi-meta">Lineas cargadas en el Estado de Resultado</div></div>
  <div class="kpi-card purple"><div class="kpi-label">Mayor Item</div><div class="kpi-value">${top?fmtMoneyShort(top.total):"-"}</div><div class="kpi-meta">${top?top.label:"-"}</div></div>`;
}
function cfItemsTable(periodo){
  const m=ER[periodo];const items=[...(m.costos_fijos_items||[])].sort((a,b)=>b.total-a.total);const total=m.totals.costos_fijos;
  let h=`<thead><tr><th>Item</th><th class="right">Monto</th><th class="right">% del Total</th></tr></thead><tbody>`;
  items.forEach(it=>{const pct=total?(it.total/total)*100:0;h+=`<tr><td style="font-weight:600">${it.label}</td><td class="right" title="${fmtMoneyFull(it.total)}">${fmtMoneyShort(it.total)}</td><td class="right"><span class="bar-mini" style="width:${pct*1.5}px"></span>${pct.toFixed(1).replace('.',',')}%</td></tr>`;});
  if(!items.length) h+=`<tr><td colspan="3" style="padding:14px;color:var(--muted)">Sin items de costos fijos detectados para este mes.</td></tr>`;
  document.getElementById("cf-items-table").innerHTML=h+"</tbody>";
}
function cfCharts(periodo){
  const m=ER[periodo];const items=[...(m.costos_fijos_items||[])].sort((a,b)=>b.total-a.total);
  destroyChart("cfItems");
  charts.cfItems=new Chart(document.getElementById("cfChartItems"),{type:"doughnut",data:{labels:items.map(i=>i.label),datasets:[{data:items.map(i=>i.total),backgroundColor:items.map((_,idx)=>CF_PALETTE[idx%CF_PALETTE.length]),borderWidth:2,borderColor:"#fff"}]},options:{responsive:true,maintainAspectRatio:false,cutout:"58%",plugins:{legend:{position:"right",labels:{boxWidth:12,font:{size:11}}},tooltip:{callbacks:{label:c=>`${c.label}: ${fmtMoneyShort(c.raw)}`}}}}});
  destroyChart("cfOs");
