  charts.cfOs=new Chart(document.getElementById("cfChartOs"),{type:"doughnut",data:{labels,datasets:[{data:m.obras_sociales.map(o=>o.costos_fijos),backgroundColor:colors,borderWidth:2,borderColor:"#fff"}]},options:{responsive:true,maintainAspectRatio:false,cutout:"58%",plugins:{legend:{position:"right",labels:{boxWidth:12,font:{size:11}}},tooltip:{callbacks:{label:c=>`${c.label}: ${fmtMoneyShort(c.raw)}`}}}}});
}
let cfCurrentPeriodo=null;
function cfComprobantesTable(periodo){
  cfCurrentPeriodo=periodo;
  const m=ER[periodo];const rows=m.costos_fijos_comprobantes||[];
  const filterItem=document.getElementById("cf-comp-filter-item").value;
  const search=(document.getElementById("cf-comp-search").value||"").toLowerCase();
  // populate item filter dropdown
  const sel=document.getElementById("cf-comp-filter-item");
  const items=[...new Set(rows.map(r=>r.item))];
  const cur=sel.value;
  sel.innerHTML='<option value="">Todos los items</option>'+items.map(i=>`<option value="${i}"${i===cur?" selected":""}>${i}</option>`).join("");
  // filter rows
  let filtered=rows;
  if(filterItem) filtered=filtered.filter(r=>r.item===filterItem);
  if(search) filtered=filtered.filter(r=>(r.proveedor||"").toLowerCase().includes(search)||(r.notas||"").toLowerCase().includes(search));
  // total
  const total=filtered.reduce((s,r)=>s+r.monto,0);
  let h=`<thead><tr><th>Item</th><th>Proveedor / Detalle</th><th class="right">Monto</th><th>Notas</th></tr></thead><tbody>`;
  if(!filtered.length){h+=`<tr><td colspan="4" style="padding:14px;color:var(--muted)">Sin comprobantes para los filtros seleccionados.</td></tr>`;}
  else{filtered.forEach(r=>{h+=`<tr><td style="color:var(--muted);font-size:12px">${r.item}</td><td style="font-weight:600">${r.proveedor}</td><td class="right" title="${fmtMoneyFull(r.monto)}">${fmtMoneyShort(r.monto)}</td><td style="color:var(--muted);font-size:12px">${r.notas}</td></tr>`;});
  h+=`<tr class="final"><td colspan="2" class="metric">TOTAL (${filtered.length} líneas)</td><td class="right">${fmtMoneyShort(total)}</td><td></td></tr>`;}
  document.getElementById("cf-comprobantes-table").innerHTML=h+"</tbody>";
}
function cfKpisCompare(){
  const sel=getCmpPeriodos().filter(p=>ER[p]);
  if(!sel.length){document.getElementById("cf-kpis").innerHTML="<p style='color:var(--muted);padding:14px'>No hay datos de Costos Fijos para los meses seleccionados.</p>";return;}
  const last=sel[sel.length-1],prev=sel.length>1?sel[sel.length-2]:null;
  const lt=ER[last].totals,pt=prev?ER[prev].totals:null;
  let meta=`Ultimo: ${P.periodos_short[last]}`;
  if(pt&&pt.costos_fijos){const d=((lt.costos_fijos-pt.costos_fijos)/Math.abs(pt.costos_fijos))*100;const dc=d>=0?"delta-neg":"delta-pos";meta=`<span class="${dc}">${d>=0?"▲":"▼"} ${Math.abs(d).toFixed(1).replace('.',',')}%</span> vs ${P.periodos_short[prev]}`;}
  document.getElementById("cf-kpis").innerHTML=`<div class="kpi-card primary"><div class="kpi-label">Total Costos Fijos</div><div class="kpi-value">${fmtMoneyShort(lt.costos_fijos)}</div><div class="kpi-meta">${meta}</div></div>`;
}
function cfTrendItems(){
  const sel=getCmpPeriodos().filter(p=>ER[p]);
  destroyChart("cfTrendItems");
  if(!sel.length) return;
  const labels=sel.map(p=>P.periodos_short[p]);
  const allLabels=new Set();
  sel.forEach(p=>(ER[p].costos_fijos_items||[]).forEach(it=>allLabels.add(it.label)));
  const items=[...allLabels];
  charts.cfTrendItems=new Chart(document.getElementById("cfTrendItems"),{type:"bar",data:{labels,datasets:items.map((lab,idx)=>({label:lab,data:sel.map(p=>{const it=(ER[p].costos_fijos_items||[]).find(x=>x.label===lab);return it?it.total:0;}),backgroundColor:CF_PALETTE[idx%CF_PALETTE.length]}))},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"top",labels:{font:{size:11},boxWidth:12}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${fmtMoneyShort(c.raw)}`}}},scales:{x:{stacked:true,grid:{display:false}},y:{stacked:true,ticks:{callback:v=>fmtMoneyShort(v),font:{size:10}},grid:{color:"#EEF2FB"}}}}});
}
function cfCmpTable(){
  const sel=getCmpPeriodos().filter(p=>ER[p]);
  if(!sel.length){document.getElementById("cf-cmp-table").innerHTML="<thead></thead><tbody><tr><td style='padding:14px;color:var(--muted)'>Sin datos para los meses seleccionados.</td></tr></tbody>";return;}
