  [...allLabels].forEach(lab=>{h+=`<tr><td class="metric">${lab}</td>`+sel.map(p=>{const it=(ER[p].costos_fijos_items||[]).find(x=>x.label===lab);return `<td class="right">${it?fmtMoneyShort(it.total):"-"}</td>`;}).join("")+"</tr>";});
  h+=`<tr class="final"><td class="metric">TOTAL</td>`+sel.map(p=>`<td class="right">${fmtMoneyShort(ER[p].totals.costos_fijos)}</td>`).join("")+"</tr>";
  document.getElementById("cf-cmp-table").innerHTML=h+"</tbody>";
